import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0011 — Dettagli implementativi di condivisione, gruppi e configurazione distribuita (M4)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0011-sharing-groups-config-details.md","filePath":"adr/0011-sharing-groups-config-details.md"}'),c={name:"adr/0011-sharing-groups-config-details.md"};function n(d,e,r,l,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0011-—-dettagli-implementativi-di-condivisione-gruppi-e-configurazione-distribuita-m4" tabindex="-1">ADR-0011 — Dettagli implementativi di condivisione, gruppi e configurazione distribuita (M4) <a class="header-anchor" href="#adr-0011-—-dettagli-implementativi-di-condivisione-gruppi-e-configurazione-distribuita-m4" aria-label="Permalink to &quot;ADR-0011 — Dettagli implementativi di condivisione, gruppi e configurazione distribuita (M4)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §1.3, §2.5, §2.6.4, §2.6.6, §3.1, §3.2.2, §3.3.2, §3.4.2, §3.4.4, §3.4.7, §3.5.3, §3.5.4, §3.6, §3.8.2, §4.3 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.4–2.6.6 (condivisione, gruppi, config), §3.3.2 (RBAC), §3.4.7 (scope), §3.5.4, §3.6, D-04…D-06</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo additivo (parametro <code>scope</code> esteso, codice <code>INVALID_STATE</code>, <code>web_client_id</code>, migrazione 0004)</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> Il limite «un <code>manager</code> gestisce i grant ma non crea share» è superato da ADR-0041 (un manager crea share dentro l&#39;ambito dello share che gestisce).</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M4 aggiunge gruppi, share con grant, mount sul desktop, Config Profile e la Web UI utente. Lo spec fissa il modello ma non alcuni dettagli che l&#39;implementazione ha dovuto scegliere.</p><h2 id="decisioni" tabindex="-1">Decisioni <a class="header-anchor" href="#decisioni" aria-label="Permalink to &quot;Decisioni&quot;">​</a></h2><ol><li><strong>Migrazione <code>0004_groups_sharing.sql</code></strong> (la <code>0003</code> è già <code>vaults</code>): <code>groups</code>, <code>group_members</code>, <code>shares</code>, <code>share_grants</code>, trigger <code>shares_vault_kind_chk</code> (<code>VAULT_ENCRYPTED</code>), <code>config_profiles</code>, <code>config_assignments</code> e la riga <code>settings[&#39;config.revision&#39;]</code>.</li><li><strong><code>scope=share:{id}</code> su tutte le operazioni sul contenuto</strong>, non solo <code>changes</code>: <code>tree</code>, <code>commit</code>, <code>blobs:check</code>, <code>PUT/GET blobs</code>, upload tus (<code>?scope=</code>), <code>files/{id}/revisions…</code>. Senza scope il vault è raggiungibile solo dal proprietario. Il percorso nel mount è relativo alla radice dello share; per un documento condiviso è il nome del file.</li><li><strong>Pacchetto <code>internal/access</code></strong> (permessi, <code>Scope</code>, interfaccia <code>Authorizer</code>) implementato da <code>sharing</code>: sync, blobs, revisions e vaults dipendono dall&#39;interfaccia, mai dalle tabelle degli share. <code>Authorize</code> risponde <code>404</code> per ciò che il chiamante non deve conoscere (share inesistente, revocato, scaduto, estraneo) e <code>403 FORBIDDEN</code> per un livello insufficiente su una risorsa visibile (es. <code>viewer</code> che scrive). L&#39;<code>Evaluator</code> applica l&#39;algoritmo §3.3.2 con la cache dei grant per richiesta.</li><li><strong>Trasformazione dei <code>changes</code> per scope</strong>: un file che esce dal prefisso appare come <code>delete</code>, uno che vi entra come <code>create</code>; per un documento condiviso un cambio di cartella che non cambia il nome è invisibile. Il changelog del vault è scandito a lotti (500, max 20 per richiesta) e filtrato; il cursore salta a <code>last_seq</code> quando lo scan lo raggiunge (la presa del lock di vault garantisce che i <code>seq</code> committati siano contigui). Dopo un <code>move_prefix</code> che rinomina la radice, i destinatari ricevono un <code>create</code> per file già noti (stesso <code>file_id</code>): il client lo tratta come aggiornamento.</li><li><strong>Confinamento dei commit</strong>: i path del mount sono rilasciati con <code>scope.Abs</code> (niente <code>..</code>, niente assoluti), le op su file esistenti verificano che il file sia nello share (altrimenti <code>NOT_FOUND</code>), uno share documento ammette solo <code>modify</code> e <code>delete</code>. <code>SHARE_ROOT_MOVE</code>: dal mount non si rinomina la radice; sul vault del proprietario un <code>move</code> file-per-file non può togliere l&#39;ultimo file da una cartella condivisa, mentre <code>move_prefix</code> trascina i <code>shares.path_prefix</code> interessati.</li><li><strong>Lettura dei blob per scope</strong>: il destinatario scarica solo blob di file che lo share copre (controllo sul percorso corrente del file: perdere l&#39;accesso a un file perde anche le sue vecchie revisioni).</li><li><strong>Inviti</strong>: un grant a un gruppo è accettato per tutto il gruppo da un suo membro qualsiasi; il rifiuto vale solo per i grant a utente (altrimenti <code>409 INVALID_STATE</code>, codice nuovo). Gli inviti pendenti non danno accesso.</li><li><strong>Eventi</strong>: canali NOTIFY <code>share_changed</code> (JSON con tipo, share ed eventuali utenti espliciti: la revoca di un grant elenca chi lo perde) e <code>config_changed</code> (revisione). Il hub consegna gli eventi di vault anche ai destinatari di share accettati (cache dei destinatari 5 s, azzerata dagli eventi di share), invia <code>ShareChanged</code> e <code>ConfigChanged</code> e li replica alla riconnessione (<code>known_seq</code>, <code>config_version</code>). Il flusso SSE usa <code>?config=</code> come analogo.</li><li><strong>Config Profile</strong>: <code>api/config-profile.schema.json</code> è il contratto, copiato in <code>internal/configprofiles/schema.json</code> per <code>go:embed</code> (un test li tiene identici). <code>version</code> in <code>GET /config/effective</code> è una revisione globale che cresce a ogni modifica di profilo, assegnazione o appartenenza a un gruppo; l&#39;ETag copre revisione e contenuto. Le chiavi <code>locked</code> sono unite tra globale e gruppi. L&#39;override utente è applicato dal client (default gestiti → scelte dell&#39;utente → chiavi <code>locked</code> forzate); <code>editor.json</code> e <code>appearance.json</code> memorizzano ormai solo le chiavi scelte dall&#39;utente. <code>linkFormat</code> nello schema usa i valori dell&#39;app (<code>shortest|path|relative</code>). Il client applica <code>sync.interval_seconds</code> (vincolante se <code>locked</code>, altrimenti default), <code>sync.max_file_size_bytes</code> (controllo prima di leggere e cifrare un file), <code>auth.redirect_mode</code> (<code>custom_scheme</code> forza lo scheme; la variabile <code>MEMOBRAIN_AUTH_REDIRECT</code> resta prioritaria), <code>security.vault_lock_minutes</code> (blocco per inattività dei vault privati, con la stessa precedenza tra default e scelta dell&#39;utente) e i feature flag (<code>features.*</code>).</li><li><strong>Desktop</strong>: ogni share accettato è un vault a sé in <code>&lt;data&gt;/mounts/&lt;share_id&gt;/</code> (stesso <code>sync.db</code>, <code>scope</code> e livello nei meta); anche i documenti singoli hanno il proprio mount (nessun mount virtuale unico &quot;Condivisi con me&quot;: il pannello Condivisione li elenca insieme). Un <code>viewer</code> ha l&#39;engine in sola lettura e le scritture dei binding rifiutate (<code>read-only:</code>), oltre al rifiuto del server. La revoca è rilevata dal <code>NOT_FOUND</code> della sync o dal reconcile dopo un evento: il mount si ferma, l&#39;utente sceglie se eliminare la copia o conservarla come vault ordinario in <code>&lt;data&gt;/kept/</code>.</li><li><strong>Web UI</strong>: <code>client-config</code> espone <code>web_client_id</code>; il binario serve la SPA con CSP rigida e SRI (<code>services/cloud/web-embed</code>); il <code>Dockerfile</code> ha uno stadio Node che la compila e la incorpora. Nessuna finestra di creazione share nella Web UI (solo gestione); la barra della quota usa <code>&lt;progress&gt;</code> perché <code>style-src &#39;self&#39;</code> vieta gli stili inline.</li></ol><h2 id="limiti-noti" tabindex="-1">Limiti noti <a class="header-anchor" href="#limiti-noti" aria-label="Permalink to &quot;Limiti noti&quot;">​</a></h2><ul><li>Nessuna API admin per gruppi e profili prima di M5 (solo servizio interno, usato dai test).</li><li>Il consumo dei template di gruppo (mount in sola lettura) è solo predisposto (<code>templates.library_share_id</code>); arriva con M6-WP3.</li><li>D-06 vieta le funzioni cross-vault: i link tra un mount e altri vault non si risolvono.</li><li>Un utente non può cedere la proprietà di un vault; un <code>manager</code> gestisce i grant ma non crea share né li revoca.</li></ul>',9)])])}const m=o(c,[["render",n]]);export{p as __pageData,m as default};
